        assertFalse(VarrockStrayCatsPlugin.isDogCall("My dog says Woof!"));
        assertFalse(VarrockStrayCatsPlugin.isDogCall("Purr...purr..."));
        assertFalse(VarrockStrayCatsPlugin.isDogCall(null));
    }

    @Test
